function c(t){return t.toString().trim().toLowerCase().replace(/[^\w\s-]/g,"").replace(/[\s_]+/g,"-").replace(/-+/g,"-").replace(/^-|-$/g,"")}const a=200;function f(t){if(!t)return 1;const e=t.replace(/<[^>]*>/g," ").trim().split(/\s+/).filter(Boolean).length;return Math.max(1,Math.round(e/a))}function u(t,n){if(!t)return"";const e=t.replace(/<[^>]*>/g," ").replace(/\s+/g," ").trim();return e.length<=n?e:e.slice(0,n).replace(/\s+\S*$/,"")+"…"}function s(t){return t?(t instanceof Date?t:new Date(t)).toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"}):""}function g(t){if(!t)return"";const n=t instanceof Date?t:new Date(t),e=Math.round((Date.now()-n.getTime())/1e3);if(e<60)return"Just now";const r=Math.round(e/60);if(r<60)return`${r}m ago`;const o=Math.round(r/60);if(o<24)return`${o}h ago`;const i=Math.round(o/24);return i<7?`${i}d ago`:s(n)}export{s as a,u as b,f as e,g as f,c as s};
